contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= dummy);

        address caller = address(this);
        bool beforeBlacklisted = c.blacklist(caller); if (__ESBMC_reverted()) return;
        bool beforeDistrFinished = c.distributionFinished(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(caller); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool afterBlacklisted = c.blacklist(caller); if (__ESBMC_reverted()) return;
        uint256 afterBalance = c.balanceOf(caller); if (__ESBMC_reverted()) return;
        uint256 amountReceived = afterBalance - beforeBalance;

        assert(reverted || (afterBlacklisted == (amountReceived > 0)));
    }

    receive() external payable {}
}

