import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dummy);
        address caller = address(this);
        bool beforeBlacklisted;
        try c.blacklist(caller) returns (bool __r) { beforeBlacklisted = __r; } catch { return; }
        bool beforeDistrFinished;
        try c.distributionFinished() returns (bool __r) { beforeDistrFinished = __r; } catch { return; }
        uint256 beforeBalance;
        try c.balanceOf(caller) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        bool reverted;
        try c.getTokens() {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterBlacklisted;
        try c.blacklist(caller) returns (bool __r) { afterBlacklisted = __r; } catch { return; }
        uint256 afterBalance;
        try c.balanceOf(caller) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 amountReceived = afterBalance - beforeBalance;
        assertTrue(reverted || (afterBlacklisted == (amountReceived > 0)));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
